UPDATE lessons SET title='Year 4, Week 35, Lesson 1: Digital safety and respect', data=json_patch(data,'{"child_mission":"Digital safety and respect include protecting personal information, kind communication, asking before sharing photos and telling a trusted adult about worries.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same science idea to a new object or material, then compare two pieces of evidence for strength.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nWhich are safe: posting your home address in a game chat; asking before tagging a friend; reusing a classmate’s photo without asking?\n\nFEEDBACK\nUnsafe; safe; unsafe.\n\nWATCH FOR\n“It’s just a joke” does not make unkind online behaviour respectful.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nCreate a class digital citizenship charter with eight pledges. Role-play two respectful responses to unsafe requests.\n\nWrite a short reflection naming one observation or step you corrected and why.","interactive_activities":null,"learning_area":"Science and Technology","learning_intention":"Digital safety and respect include protecting personal information, kind communication, asking before sharing photos and telling a trusted adult about worries.","lesson_number":1,"lesson_role":"Investigate","materials":["Paper or typed answer space","Pencil","Optional: safe everyday objects for observation"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["ST2-DAT-01"],"parent_notes":"Parent: Marking guidance for the independent task: Create a class digital citizenship charter with eight pledges. Role-play two respectful responses to unsafe requests. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Sample: new object/context, two named observations, claim about safety linked to that evidence.\n\nParent: Written model 2: Sample misconception: “It’s just a joke” does not make unkind online behaviour respectful.. Correction: Unsafe; safe; unsafe. with evidence.\n\nParent: Likely misconception: “It’s just a joke” does not make unkind online behaviour respectful. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Investigate or describe a fresh example (not the worked objects) that uses safety. Record evidence and explain how it supports your claim.\n\nParent: Short-answer focus 2: Name one science misconception about safety, correct it with evidence, and say why the correction works.\n\nParent: Marking notes: Accept a new example with named observations and a claim–evidence link about safety. Reject title-only labels with no observation. / Accept a misconception plus corrected claim and evidence reason for safety. Reject wording changes that leave the same error..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"This matches the taught method for safety. The other choices miss a key step or use a common mistake.","options":["Unsafe; safe; unsafe","“It’s just a joke” does not make unkind online behaviour respectful","A claim that names no evidence from the lesson material","A method that skips the key step taught in this lesson"],"question":"Which are safe: posting your home address in a game chat; asking before tagging a friend; reusing a classmate’s photo without asking?","type":"multiple_choice"},{"correct_index":1,"explanation":"This is the misconception to avoid for safety; the other choices align with the lesson method. The other choices miss a key step or use a common mistake.","options":["Careful use of respect and explain why it matters with clear evidence","“It’s just a joke” does not make unkind online behaviour respectful","Digital safety and respect include protecting personal information, kind communication, asking before sharing photos","Unsafe; safe; unsafe"],"question":"Which statement is a common mistake when working with safety?","type":"multiple_choice"},{"correct_index":1,"explanation":"Understanding is shown by new evidence and a named respect and explain why it matters, not by copying the model. The other choices miss a key step or use a common mistake.","options":["Name respect and explain why it matters only, without linking it to safety","Apply safety to new material and name the respect and explain why it matters used","Repeat the worked example wording with no new evidence","“It’s just a joke” does not make unkind online behaviour respectful"],"question":"Which response best applies safety with new evidence?","type":"multiple_choice"},{"correct_index":2,"explanation":"Trustworthy science claims rest on observable evidence linked to the claim. The other choices miss a key step or use a common mistake.","options":["Copy a label from the lesson title with no observation","“It’s just a joke” does not make unkind online behaviour respectful","Use observable features or measurements as evidence, not appearance alone","Decide from which object looks most exciting"],"question":"New examples: a charging phone, a nesting bird, a glass marble, a fallen dry leaf. Which claim about safety is most trustworthy?","type":"multiple_choice"},{"correct_index":1,"explanation":"Science claims need named observations linked to the claim. The other choices miss a key step or use a common mistake.","options":["“It’s just a joke” does not make unkind online behaviour respectful","A named observation plus how it supports the claim","A longer story with no observation","A label copied from the title with no evidence"],"question":"Which record best supports a science claim about safety?","type":"multiple_choice"},{"correct_index":3,"explanation":"The strongest choice applies the taught idea about safety with evidence. The other choices miss a key step or use a common mistake.","options":["“It’s just a joke” does not make unkind online behaviour respectful","Change several conditions at once so something happens faster","Ignore measurements and decide by which looks nicer","Unsafe; safe; unsafe"],"question":"Using this science idea — Digital safety and respect include protecting personal information, kind communication, asking — which choice is strongest?","type":"multiple_choice"},{"correct_index":0,"explanation":"Fair tests change one variable, control the rest, and use recorded evidence. The other choices miss a key step or use a common mistake.","options":["Change one variable and keep the other conditions the same","Change several conditions at once so something happens faster","Stop early when you like the first result","Ignore measurements and decide by which looks nicer"],"question":"Which investigation design best tests an idea about safety?","type":"multiple_choice"},{"correct_index":0,"explanation":"Scientific predictions stay open to new observations rather than protecting a first guess. The other choices miss a key step or use a common mistake.","options":["If the observed feature changes, the claim about safety should change with it","Any exciting story about the object must be true","“It’s just a joke” does not make unkind online behaviour respectful","Results that disagree with the first guess should be discarded"],"question":"Which prediction about safety can be checked with evidence?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Accept a new example with named observations and a claim–evidence link about safety. Reject title-only labels with no observation.","question":"Investigate or describe a fresh example (not the worked objects) that uses safety. Record evidence and explain how it supports your claim.","sample_answer":"Sample: new object/context, two named observations, claim about safety linked to that evidence.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Accept a misconception plus corrected claim and evidence reason for safety. Reject wording changes that leave the same error.","question":"Name one science misconception about safety, correct it with evidence, and say why the correction works.","sample_answer":"Sample misconception: “It’s just a joke” does not make unkind online behaviour respectful.. Correction: Unsafe; safe; unsafe. with evidence.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent evidence and reflection, with reasons where requested.","review_status":"unreviewed","seed_key":"s2-sci-y4-w35-l1","sort_activity":null,"source_note":"Proposed Stage 2 NESA Science and Technology alignment using catalogue outcome codes; content-point mapping remains pending.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise safety.","Read the mission before you start observing or testing.","Keep the property or variable you are studying in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your evidence with the feedback.","Adjust anything that does not match the method."],"learn":["Study how the first demonstration is built.","Point to the observation or step that carries the idea.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore observations or fair tests.","Prefer accurate evidence over a guess that merely looks neat."],"submit":["Confirm that your evidence and reason are both present.","Proofread labels, measurements and sequence of steps.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact observation or test step before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and list the key observations.","Say what each observation shows about the idea.","A final label alone is weaker than recorded evidence."],"teach2":["Compare a weak claim with stronger evidence.","Change the claim or method, not only how neat the drawing looks.","Name the mistake you are repairing."],"teach3":["Choose a fresh object or context that still uses the same skill.","Write one reason in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include original evidence and a short reason.","Save work that shows the skill on new objects or data."]},"subject":"Digital Technologies","success_criteria":["I can use safety with a specific example from this lesson.","I can identify respect and explain why it matters.","I can practise privacy independently on a new prompt.","I can notice online needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":0,"explanation":"Digital safety and respect include protecting personal information, kind communication, asking before sharing photos and telling a trusted adult about worries.","options":["Digital safety and respect include protecting personal information, kind communication, asking before sharing photos","A claim unrelated to the observation or test","An answer copied without understanding","A guess with no evidence"],"question":"Which choice best applies this lesson idea about safety with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nDo not share passwords/address. Think before posting. Credit others’ work. Pause–block–tell for unkind messages.\n\nTRY FIRST\nWhich are safe: posting your home address in a game chat; asking before tagging a friend; reusing a classmate’s photo without asking?\n\nFEEDBACK\nUnsafe; safe; unsafe.","explain":"Digital safety and respect include protecting personal information, kind communication, asking before sharing photos and telling a trusted adult about worries.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"“It’s just a joke” does not make unkind online behaviour respectful. Correct the claim or method, not just the neatness of the diagram.","title":"Understand and model","visual":[{"alt":"Digital safety.","caption":"Pause–block–tell.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Privacy</text><text x=\"28\" y=\"78\">no address/password</text><text x=\"358\" y=\"42\">Respect</text><text x=\"358\" y=\"78\">ask before share</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which observation matters most.","who":"pip"},{"text":"Name the observations, properties or test steps that carry the idea before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: Do not share passwords/address. Think before posting. Credit others’ work. Pause–block–tell for unkind messages. Then write your own evidence.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which observation matters most.\nJuno: Name the observations, properties or test steps that carry the idea before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: Do not share passwords/address. Think before posting. Credit others’ work. Pause–block–tell for unkind messages. Then write your own evidence."}}]},{"check":{"correct_index":0,"explanation":"Make the science idea visible: name the observation, source or example you used and say why it supports the claim.","options":["Make the science idea visible: name the observation, source or example you used and say why it supports the claim","A claim unrelated to the observation or test","An answer copied without understanding","A guess with no evidence"],"question":"Which choice best applies this lesson idea about safety with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nDo not share passwords/address. Think before posting. Credit others’ work. Pause–block–tell for unkind messages. Look at each observation, source detail or example that carries the idea.\n\nTRY FIRST\nList the key observations, sources or steps from the model and say what each one shows.\n\nFEEDBACK\nThe most useful record names the evidence and the reason it supports the claim, not only a label.","explain":"Make the science idea visible: name the observation, source or example you used and say why it supports the claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Writing only a final label without evidence does not show science thinking. Correct the claim or method, not just the neatness of the diagram.","title":"Show the evidence","visual":[{"alt":"Role-play safe replies.","caption":"Citizenship charter.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Charter</text><text x=\"28\" y=\"78\">eight pledges</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">just a joke excuse</text></g></svg>"}]},{"check":{"correct_index":0,"explanation":"Use an intentionally incorrect claim as a comparison.","options":["Use an intentionally incorrect claim as a comparison","A claim unrelated to the observation or test","An answer copied without understanding","A guess with no evidence"],"question":"Which choice best applies this lesson idea about safety with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\n“It’s just a joke” does not make unkind online behaviour respectful. Here is a more productive model: Do not share passwords/address. Think before posting. Credit others’ work. Pause–block–tell for unkind messages.\n\nTRY FIRST\nDescribe why the warned-against claim fails, then write a corrected claim with evidence.\n\nFEEDBACK\nUnsafe; safe; unsafe.","explain":"Use an intentionally incorrect claim as a comparison. Name its specific science error, then show the corrected evidence-based claim.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Changing the wording without repairing the evidence does not fix the error. “It’s just a joke” does not make unkind online behaviour respectful. Correct the claim or method, not just the neatness of the diagram.","title":"Test a misconception"},{"check":{"correct_index":3,"explanation":"Use the same science idea on a new place, person, source or context, not a copy of the worked example.","options":["A claim unrelated to the observation or test","An answer copied without understanding","A guess with no evidence","Use the same science idea on a new place, person, source or context, not a copy of the worked example"],"question":"Which choice best applies this lesson idea about safety with clear evidence?","type":"multiple_choice"},"example":"WORKED MODEL\nDigital safety and respect include protecting personal information, kind communication, asking before sharing photos and telling a trusted adult about worries. Now choose a different example to show you can transfer the idea.\n\nTRY FIRST\nInquire into or describe one fresh example that uses the same skill and write a short evidence-based reason.\n\nFEEDBACK\nThe new example should use the same science idea as the model, but contain different evidence.","explain":"Use the same science idea on a new place, person, source or context, not a copy of the worked example. Review accuracy of evidence.\n\nWHY IT MATTERS\nThis helps the learner base claims on observation, fair tests and design evidence, rather than guessing from a picture alone. Keep every claim linked to what was seen or measured.\n\nHOW TO WORK\nRead the worked example and name the observations, properties or test steps that carry the idea. Before looking at the correction, make your own attempt using the exact question provided. Compare your record with the feedback: did you use the same skill and show your evidence? If a result is uncertain, identify what would have to be observed or tested again. One deliberate, evidence-based revision is more useful than writing a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to new evidence. Correct the claim or method, not just the neatness of the diagram.","title":"Transfer to a new investigation"}],"title":"Year 4, Week 35, Lesson 1: Digital safety and respect","unit_number":7,"unit_title":"Digital technologies: algorithms and robotics","week":35,"week_in_unit":5,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nDo not share passwords/address. Think before posting. Credit others’ work. Pause–block–tell for unkind messages.\n\nWrite what makes this example accurate, naming the observations, properties or test steps used.","worked_visuals":[{"alt":"Digital safety.","caption":"Pause–block–tell.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Privacy</text><text x=\"28\" y=\"78\">no address/password</text><text x=\"358\" y=\"42\">Respect</text><text x=\"358\" y=\"78\">ask before share</text></g></svg>"},{"alt":"Role-play safe replies.","caption":"Citizenship charter.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Charter</text><text x=\"28\" y=\"78\">eight pledges</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">just a joke excuse</text></g></svg>"}],"year_level":"Year 4"}') WHERE seed_key='s2-sci-y4-w35-l1' AND family_id IS NULL;
